class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        INF = float('inf')
        # dp[c1][c2] stores the min cost for the current pair of houses (k, n-1-k)
        # to have colors c1 and c2 respectively.
        dp = [[INF] * 3 for _ in range(3)]

        # Base case: k = 0 (houses 0 and n-1)
        for c1 in range(3):
            for c2 in range(3):
                if c1 != c2:
                    dp[c1][c2] = cost[0][c1] + cost[n-1][c2]

        # Iterate for k from 1 to n/2 - 1
        for k in range(1, n // 2):
            new_dp = [[INF] * 3 for _ in range(3)]
            # Current pair: k and n-1-k
            # Previous pair: k-1 and n-k

            for c1 in range(3):
                for c2 in range(3):
                    # Constraint: color[k] != color[n-1-k]
                    if c1 == c2:
                        continue

                    for prev_c1 in range(3):
                        for prev_c2 in range(3):
                            # Constraint: color[k-1] != color[k]
                            if prev_c1 == c1:
                                continue
                            # Constraint: color[n-k] != color[n-1-k]
                            if prev_c2 == c2:
                                continue
                            # Constraint: color[k-1] != color[n-k] (from previous step)
                            if prev_c1 == prev_c2:
                                continue

                            if dp[prev_c1][prev_c2] != INF:
                                new_dp[c1][c2] = min(new_dp[c1][c2], dp[prev_c1][prev_c2] + cost[k][c1] + cost[n-1-k][c2])

            dp = new_dp

        ans = INF
        for c1 in range(3):
            for c2 in range(3):
                ans = min(ans, dp[c1][c2])

        return ans

class Solution:
    def maxContainers(self, n: int, w: int, maxWeight: int) -> int:
        # The deck has n * n cells.
        # Each container weighs w.
        # The ship has a maximum weight capacity of maxWeight.

        # The number of containers is limited by two factors:
        # 1. The number of cells available on the deck: n * n
        # 2. The ship's weight capacity: maxWeight // w (integer division)

        # We return the minimum of these two values.
        return min(n * n, maxWeight // w)

