from collections import defaultdict

class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        if n == 0:
            return 0

        # Build adjacency list for the graph
        adj = defaultdict(list)

        # Check all pairs and add edges if intersection >= k
        for i in range(n):
            for j in range(i + 1, n):
                # Compute intersection of properties[i] and properties[j]
                set_i = set(properties[i])
                set_j = set(properties[j])
                intersection = len(set_i & set_j)

                if intersection >= k:
                    adj[i].append(j)
                    adj[j].append(i)

        # Track visited nodes for DFS traversal
        visited = [False] * n
        connected_components = 0

        # DFS function to traverse connected component
        def dfs(node, visited):
            visited[node] = True
            for neighbor in adj[node]:
                if not visited[neighbor]:
                    dfs(neighbor, visited)

        # Count connected components
        for i in range(n):
            if not visited[i]:
                dfs(i, visited)
                connected_components += 1

        return connected_components

