class Solution:
    def maxAdjacentDistance(self, nums: List[int]) -> int:
        n = len(nums)
        max_diff = 0
        for i in range(n):
            # Calculate the absolute difference between the current element and the next element.
            # Since the array is circular, the next element after the last one (index n-1) is the first one (index 0).
            # We handle this wrap-around using the modulo operator: (i + 1) % n.
            diff = abs(nums[i] - nums[(i + 1) % n])
            if diff > max_diff:
                max_diff = diff
        return max_diff

