class Solution:
    def sumOfGoodNumbers(self, nums: List[int], k: int) -> int:
        total_sum = 0
        n = len(nums)
        for i in range(n):
            is_good = True
            # Check index i - k
            if i - k >= 0:
                # If nums[i] is not strictly greater than nums[i-k], it is not good
                if nums[i] <= nums[i - k]:
                    is_good = False
            # Check index i + k
            if i + k < n:
                # If nums[i] is not strictly greater than nums[i+k], it is not good
                if nums[i] <= nums[i + k]:
                    is_good = False

            if is_good:
                total_sum += nums[i]
        return total_sum

