from itertools import permutations

class Solution:
    def totalNumbers(self, digits: List[int]) -> int:
        distinct_numbers = set()

        # Iterate through all permutations of length 3 from the input digits list.
        # itertools.permutations handles the generation of permutations based on indices,
        # which correctly accounts for duplicate digits in the input.
        for p in permutations(digits, 3):
            # Construct the 3-digit number from the permutation tuple
            num = p[0] * 100 + p[1] * 10 + p[2]

            # Check if the number is even
            if num % 2 == 0:
                # Check if there are no leading zeros (the first digit cannot be 0)
                if p[0] != 0:
                    # Add the valid number to a set to ensure distinctness
                    distinct_numbers.add(num)

        return len(distinct_numbers)
